  };

  const increment = (direction: 1 | -1, event: KeyboardEvent<HTMLInputElement>) => {
    const modifier = event.shiftKey ? shiftMultiplier : event.altKey ? altMultiplier : 1;
    applyValue((value ?? 0) + direction * step * modifier, true);
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (disabled || readOnly) return;
    if (event.key === 'ArrowUp' || event.key === 'ArrowDown') {
      event.preventDefault();
      increment(event.key === 'ArrowUp' ? 1 : -1, event);
      return;
    }
    if (event.key === 'Enter') {
      event.preventDefault();
      if (commitDraft()) inputRef.current?.select();
      return;
    }
    if (event.key === 'Escape') {
      event.preventDefault();
      setDraft(formatValue(value, precision));
      setError(null);
      inputRef.current?.blur();
    }
  };

  const handleBlur = (_event: FocusEvent<HTMLInputElement>) => {
    setEditing(false);
    if (!error && draft === formatValue(value, precision)) return;
    if (!commitDraft()) setDraft(formatValue(value, precision));
  };

  return (
    <label
      className={cx(
        'ui-number-field',
        error && 'ui-number-field--invalid',
        disabled && 'ui-number-field--disabled',
        className,
      )}
    >
      {label ? (
        <span className="ui-number-field__label" aria-hidden="true">
          {label}
        </span>
      ) : null}
      <input
        ref={inputRef}
        className="ui-number-field__input"
        type="text"
        inputMode="decimal"
        autoComplete="off"
        spellCheck={false}
        value={draft}
        placeholder={placeholder}
        disabled={disabled}
        readOnly={readOnly}
        aria-label={ariaLabel}
        aria-invalid={error ? true : undefined}
        aria-errormessage={error ? errorId : undefined}
        onChange={(event) => {
          setDraft(event.currentTarget.value);
          setError(null);
        }}
        onFocus={(event) => {
          setEditing(true);
          event.currentTarget.select();
        }}
        onBlur={handleBlur}
        onKeyDown={handleKeyDown}
      />
      {suffix ? <span className="ui-number-field__suffix">{suffix}</span> : null}
      <span id={errorId} className="ui-visually-hidden" role="alert">
        {error}
      </span>
    </label>
  );
}

import { applyMatrixToPoint, matrixScaleFactors, tryInvertMatrix } from './matrix2d'
import type { Matrix2D } from './matrix2d'
import { expandRect, insetRect, normalizeRect, rectContainsPoint } from './rect'
import type { Rect } from './rect'
import { distanceSquaredVec2, GEOMETRY_EPSILON } from './vec2'
import type { Vec2 } from './vec2'

export interface CornerRadii {
  readonly topLeft: number
  readonly topRight: number
  readonly bottomRight: number
  readonly bottomLeft: number
}

export interface RectHitShape {
  readonly kind: 'rect'
  readonly rect: Rect
  readonly cornerRadii?: number | CornerRadii
}

export interface EllipseHitShape {
  readonly kind: 'ellipse'
  readonly rect: Rect
}

export interface LineHitShape {
  readonly kind: 'line'
  readonly start: Vec2
  readonly end: Vec2
  readonly strokeWidth: number
}

export interface PolygonHitShape {
  readonly kind: 'polygon'
  readonly points: readonly Vec2[]
}

export type HitShape = RectHitShape | EllipseHitShape | LineHitShape | PolygonHitShape

export interface HitTestOptions {
  /** Filled interiors participate by default for closed shapes. */
  readonly fill?: boolean
  /** Local-space stroke width. Line shapes use their own width when omitted. */
  readonly strokeWidth?: number
  /** Extra local-space hit slop around the visible geometry. */
  readonly tolerance?: number
}

export function uniformCornerRadii(radius: number): CornerRadii {
  return { topLeft: radius, topRight: radius, bottomRight: radius, bottomLeft: radius }
}

/** Applies the CSS corner scaling rule so adjacent radii never overlap. */
export function normalizeCornerRadii(radii: number | CornerRadii, rect: Rect): CornerRadii {
  const normalized = normalizeRect(rect)
  const source = typeof radii === 'number' ? uniformCornerRadii(radii) : radii
  const clamped: CornerRadii = {
    topLeft: Math.max(0, source.topLeft),
    topRight: Math.max(0, source.topRight),
    bottomRight: Math.max(0, source.bottomRight),
    bottomLeft: Math.max(0, source.bottomLeft),
  }

  const ratios = [
    ratioOrOne(normalized.width, clamped.topLeft + clamped.topRight),
    ratioOrOne(normalized.width, clamped.bottomLeft + clamped.bottomRight),
    ratioOrOne(normalized.height, clamped.topLeft + clamped.bottomLeft),
    ratioOrOne(normalized.height, clamped.topRight + clamped.bottomRight),
  ]
  const scale = Math.min(1, ...ratios)

  return {
    topLeft: clamped.topLeft * scale,
    topRight: clamped.topRight * scale,
    bottomRight: clamped.bottomRight * scale,
    bottomLeft: clamped.bottomLeft * scale,
  }
}

export function pointInRoundedRect(
  point: Vec2,
  rect: Rect,
  radii: number | CornerRadii = 0,
  tolerance = 0,
): boolean {
  const normalized = normalizeRect(rect)
  const expanded = tolerance === 0 ? normalized : expandRect(normalized, tolerance)
  const corners = normalizeCornerRadii(addToCornerRadii(radii, tolerance), expanded)

  if (!rectContainsPoint(expanded, point)) return false

  const left = expanded.x
  const top = expanded.y
  const right = left + expanded.width
  const bottom = top + expanded.height

  if (corners.topLeft > 0 && point.x < left + corners.topLeft && point.y < top + corners.topLeft) {
    return pointInCircle(point, { x: left + corners.topLeft, y: top + corners.topLeft }, corners.topLeft)
  }
  if (corners.topRight > 0 && point.x > right - corners.topRight && point.y < top + corners.topRight) {
    return pointInCircle(point, { x: right - corners.topRight, y: top + corners.topRight }, corners.topRight)
  }
  if (
    corners.bottomRight > 0 &&
    point.x > right - corners.bottomRight &&
    point.y > bottom - corners.bottomRight
  ) {
    return pointInCircle(
      point,
      { x: right - corners.bottomRight, y: bottom - corners.bottomRight },
      corners.bottomRight,
    )
  }
  if (corners.bottomLeft > 0 && point.x < left + corners.bottomLeft && point.y > bottom - corners.bottomLeft) {
    return pointInCircle(
      point,
      { x: left + corners.bottomLeft, y: bottom - corners.bottomLeft },
      corners.bottomLeft,
    )
  }

  return true
}

export function pointInEllipse(point: Vec2, rect: Rect, tolerance = 0): boolean {
  const normalized = normalizeRect(rect)
  const radiusX = normalized.width / 2 + tolerance
  const radiusY = normalized.height / 2 + tolerance
  if (radiusX <= 0 || radiusY <= 0) return false

  const centerX = normalized.x + normalized.width / 2
  const centerY = normalized.y + normalized.height / 2
  const normalizedX = (point.x - centerX) / radiusX
  const normalizedY = (point.y - centerY) / radiusY
  return normalizedX * normalizedX + normalizedY * normalizedY <= 1 + GEOMETRY_EPSILON
}

export function distancePointToSegment(point: Vec2, start: Vec2, end: Vec2): number {
  const segmentX = end.x - start.x
  const segmentY = end.y - start.y
  const lengthSquared = segmentX * segmentX + segmentY * segmentY
  if (lengthSquared <= GEOMETRY_EPSILON) return Math.sqrt(distanceSquaredVec2(point, start))

  const projection = Math.max(
    0,
    Math.min(1, ((point.x - start.x) * segmentX + (point.y - start.y) * segmentY) / lengthSquared),
  )
  const nearest = { x: start.x + segmentX * projection, y: start.y + segmentY * projection }
  return Math.sqrt(distanceSquaredVec2(point, nearest))
}

export function pointOnLine(point: Vec2, start: Vec2, end: Vec2, tolerance: number): boolean {
  return distancePointToSegment(point, start, end) <= tolerance
}

export function pointInPolygon(point: Vec2, points: readonly Vec2[], edgeTolerance = GEOMETRY_EPSILON): boolean {
  if (points.length < 3) return false
  if (pointNearPolygonEdge(point, points, edgeTolerance)) return true

  let inside = false
  for (let currentIndex = 0, previousIndex = points.length - 1; currentIndex < points.length; previousIndex = currentIndex, currentIndex += 1) {
    const current = points[currentIndex]
    const previous = points[previousIndex]
    if (current === undefined || previous === undefined) continue

    const crossesRay =
      current.y > point.y !== previous.y > point.y &&
      point.x < ((previous.x - current.x) * (point.y - current.y)) / (previous.y - current.y) + current.x
    if (crossesRay) inside = !inside
  }
  return inside
}

export function hitTestShape(point: Vec2, shape: HitShape, options: HitTestOptions = {}): boolean {
  const tolerance = Math.max(0, options.tolerance ?? 0)
  const includeFill = options.fill ?? shape.kind !== 'line'
  const strokeWidth = Math.max(
    0,
    options.strokeWidth ?? (shape.kind === 'line' ? shape.strokeWidth : 0),
  )

  switch (shape.kind) {
    case 'rect':
      return hitTestRect(point, shape, includeFill, strokeWidth, tolerance)
    case 'ellipse':
      return hitTestEllipse(point, shape.rect, includeFill, strokeWidth, tolerance)
    case 'line':
      return pointOnLine(point, shape.start, shape.end, strokeWidth / 2 + tolerance)
    case 'polygon':
      return hitTestPolygon(point, shape.points, includeFill, strokeWidth, tolerance)
    default:
      return assertNever(shape)
  }
}

/**
 * Converts a world point to shape-local coordinates before exact testing.
 * Hit tolerance is specified in world units and conservatively converted through scale.
 */
export function hitTestTransformedShape(
  worldPoint: Vec2,
  shape: HitShape,
  worldMatrix: Matrix2D,
  options: HitTestOptions = {},
): boolean {
  const inverse = tryInvertMatrix(worldMatrix)
  if (inverse === null) return false

  const inverseScales = matrixScaleFactors(inverse)
  const localTolerance = (options.tolerance ?? 0) * Math.max(inverseScales.x, inverseScales.y)
  return hitTestShape(applyMatrixToPoint(inverse, worldPoint), shape, {
    ...options,
    tolerance: localTolerance,
  })
}

function hitTestRect(
  point: Vec2,
  shape: RectHitShape,
  includeFill: boolean,
  strokeWidth: number,
  tolerance: number,
): boolean {
  const radii = shape.cornerRadii ?? 0
  if (includeFill && pointInRoundedRect(point, shape.rect, radii, tolerance)) return true
  if (strokeWidth <= 0 && tolerance <= 0) return false

  const boundarySlop = strokeWidth / 2 + tolerance
  if (!pointInRoundedRect(point, shape.rect, radii, boundarySlop)) return false

  const normalized = normalizeRect(shape.rect)
  const inner = insetRect(normalized, boundarySlop)
  if (inner.width <= 0 || inner.height <= 0) return true
  return !pointInRoundedRect(point, inner, subtractFromCornerRadii(radii, boundarySlop))
}

function hitTestEllipse(
  point: Vec2,
  rect: Rect,
  includeFill: boolean,
  strokeWidth: number,
  tolerance: number,
): boolean {
  if (includeFill && pointInEllipse(point, rect, tolerance)) return true
  const boundarySlop = strokeWidth / 2 + tolerance
  if (boundarySlop <= 0 || !pointInEllipse(point, rect, boundarySlop)) return false

  const inner = insetRect(normalizeRect(rect), boundarySlop)
  return inner.width <= 0 || inner.height <= 0 || !pointInEllipse(point, inner)
}

function hitTestPolygon(
  point: Vec2,
  points: readonly Vec2[],
  includeFill: boolean,
  strokeWidth: number,
  tolerance: number,
): boolean {
  if (includeFill && pointInPolygon(point, points, tolerance)) return true
  return pointNearPolygonEdge(point, points, strokeWidth / 2 + tolerance)
}

function pointNearPolygonEdge(point: Vec2, points: readonly Vec2[], tolerance: number): boolean {
  if (points.length < 2) return false
  for (let index = 0; index < points.length; index += 1) {
    const start = points[index]
    const end = points[(index + 1) % points.length]
    if (start !== undefined && end !== undefined && pointOnLine(point, start, end, tolerance)) return true
  }
  return false
}

function pointInCircle(point: Vec2, center: Vec2, radius: number): boolean {
  return distanceSquaredVec2(point, center) <= radius * radius + GEOMETRY_EPSILON
}

function addToCornerRadii(radii: number | CornerRadii, amount: number): CornerRadii {
  const source = typeof radii === 'number' ? uniformCornerRadii(radii) : radii
  return {
    topLeft: Math.max(0, source.topLeft + amount),
    topRight: Math.max(0, source.topRight + amount),
    bottomRight: Math.max(0, source.bottomRight + amount),
    bottomLeft: Math.max(0, source.bottomLeft + amount),
  }
}

function subtractFromCornerRadii(radii: number | CornerRadii, amount: number): CornerRadii {
  return addToCornerRadii(radii, -amount)
}

function ratioOrOne(numerator: number, denominator: number): number {
  return denominator <= GEOMETRY_EPSILON ? 1 : numerator / denominator
}

function assertNever(value: never): never {
  throw new Error(`Unsupported hit shape: ${JSON.stringify(value)}`)
}
import { applyMatrixToPoint, matrixAroundPoint, rotationMatrix } from './matrix2d'
import type { Matrix2D } from './matrix2d'
import { aabbFromPoints, rectCenter, rectCorners } from './rect'
import type { AABB, Rect } from './rect'
import type { Vec2 } from './vec2'

export function transformRectCorners(rect: Rect, matrix: Matrix2D): readonly [Vec2, Vec2, Vec2, Vec2] {
  const [topLeft, topRight, bottomRight, bottomLeft] = rectCorners(rect)
  return [
    applyMatrixToPoint(matrix, topLeft),
    applyMatrixToPoint(matrix, topRight),
    applyMatrixToPoint(matrix, bottomRight),
    applyMatrixToPoint(matrix, bottomLeft),
  ]
}

export function transformRectBounds(rect: Rect, matrix: Matrix2D): AABB {
  return aabbFromPoints(transformRectCorners(rect, matrix))
}

export function rotatedRectCorners(
  rect: Rect,
  radians: number,
  pivot: Vec2 = rectCenter(rect),
): readonly [Vec2, Vec2, Vec2, Vec2] {
  return transformRectCorners(rect, matrixAroundPoint(rotationMatrix(radians), pivot))
}

export function rotatedRectBounds(rect: Rect, radians: number, pivot: Vec2 = rectCenter(rect)): AABB {
  return aabbFromPoints(rotatedRectCorners(rect, radians, pivot))
}
import type { Vec2 } from './vec2'

export interface Rect {
  readonly x: number
  readonly y: number
  readonly width: number
  readonly height: number
}

/** Axis-aligned bounds in any coordinate space. */
export interface AABB {
  readonly minX: number
  readonly minY: number
  readonly maxX: number
  readonly maxY: number
}

export function normalizeRect(rect: Rect): Rect {
  const x = rect.width < 0 ? rect.x + rect.width : rect.x
  const y = rect.height < 0 ? rect.y + rect.height : rect.y
  return { x, y, width: Math.abs(rect.width), height: Math.abs(rect.height) }
}

export function rectFromPoints(start: Vec2, end: Vec2): Rect {
  return normalizeRect({ x: start.x, y: start.y, width: end.x - start.x, height: end.y - start.y })
}

export function rectCenter(rect: Rect): Vec2 {
  return { x: rect.x + rect.width / 2, y: rect.y + rect.height / 2 }
}

export function rectCorners(rect: Rect): readonly [Vec2, Vec2, Vec2, Vec2] {
  const normalized = normalizeRect(rect)
  const right = normalized.x + normalized.width
  const bottom = normalized.y + normalized.height
  return [
    { x: normalized.x, y: normalized.y },
    { x: right, y: normalized.y },
    { x: right, y: bottom },
    { x: normalized.x, y: bottom },
  ]
}

export function insetRect(rect: Rect, amountX: number, amountY = amountX): Rect {
  return {
    x: rect.x + amountX,
    y: rect.y + amountY,
    width: Math.max(0, rect.width - amountX * 2),
    height: Math.max(0, rect.height - amountY * 2),
  }
}

export function expandRect(rect: Rect, amountX: number, amountY = amountX): Rect {
  return insetRect(rect, -amountX, -amountY)
}

export function rectContainsPoint(rect: Rect, point: Vec2, tolerance = 0): boolean {
  const normalized = normalizeRect(rect)
  return (
    point.x >= normalized.x - tolerance &&
    point.x <= normalized.x + normalized.width + tolerance &&
    point.y >= normalized.y - tolerance &&
    point.y <= normalized.y + normalized.height + tolerance
  )
}

export function rectsIntersect(left: Rect, right: Rect): boolean {
  return aabbsIntersect(rectToAabb(left), rectToAabb(right))
}

export function rectToAabb(rect: Rect): AABB {
  const normalized = normalizeRect(rect)
  return {
    minX: normalized.x,
    minY: normalized.y,
    maxX: normalized.x + normalized.width,
    maxY: normalized.y + normalized.height,
  }
}

export function aabbToRect(bounds: AABB): Rect {
  return {
    x: bounds.minX,
    y: bounds.minY,
    width: bounds.maxX - bounds.minX,
    height: bounds.maxY - bounds.minY,
  }
}

export function aabbFromPoints(points: readonly Vec2[]): AABB {
  const first = points[0]
  if (first === undefined) throw new RangeError('Cannot create bounds from an empty point set')

  let minX = first.x
  let minY = first.y
  let maxX = first.x
  let maxY = first.y

  for (let index = 1; index < points.length; index += 1) {
    const point = points[index]
    if (point === undefined) continue
    minX = Math.min(minX, point.x)
    minY = Math.min(minY, point.y)
    maxX = Math.max(maxX, point.x)
    maxY = Math.max(maxY, point.y)
  }

  return { minX, minY, maxX, maxY }
}

export function aabbCenter(bounds: AABB): Vec2 {
  return { x: (bounds.minX + bounds.maxX) / 2, y: (bounds.minY + bounds.maxY) / 2 }
}

export function expandAabb(bounds: AABB, amount: number): AABB {
  return {
    minX: bounds.minX - amount,
    minY: bounds.minY - amount,
    maxX: bounds.maxX + amount,
    maxY: bounds.maxY + amount,
  }
}

export function unionAabb(left: AABB, right: AABB): AABB {
  return {
    minX: Math.min(left.minX, right.minX),
    minY: Math.min(left.minY, right.minY),
    maxX: Math.max(left.maxX, right.maxX),
    maxY: Math.max(left.maxY, right.maxY),
  }
}

export function intersectAabb(left: AABB, right: AABB): AABB | null {
  const minX = Math.max(left.minX, right.minX)
  const minY = Math.max(left.minY, right.minY)
  const maxX = Math.min(left.maxX, right.maxX)
  const maxY = Math.min(left.maxY, right.maxY)
  return minX <= maxX && minY <= maxY ? { minX, minY, maxX, maxY } : null
}

export function aabbContainsPoint(bounds: AABB, point: Vec2, tolerance = 0): boolean {
  return (
    point.x >= bounds.minX - tolerance &&
    point.x <= bounds.maxX + tolerance &&
    point.y >= bounds.minY - tolerance &&
    point.y <= bounds.maxY + tolerance
  )
}

export function aabbsIntersect(left: AABB, right: AABB): boolean {
  return !(
    left.maxX < right.minX ||
    left.minX > right.maxX ||
    left.maxY < right.minY ||
    left.minY > right.maxY
  )
}

export function aabbContainsAabb(container: AABB, candidate: AABB): boolean {
  return (
    candidate.minX >= container.minX &&
    candidate.maxX <= container.maxX &&
    candidate.minY >= container.minY &&
    candidate.maxY <= container.maxY
  )
}
/** A point or vector in a two-dimensional Cartesian coordinate space. */
export interface Vec2 {
  readonly x: number
  readonly y: number
}

export const GEOMETRY_EPSILON = 1e-9
export const ZERO_VEC2: Vec2 = Object.freeze({ x: 0, y: 0 })

export function vec2(x: number, y: number): Vec2 {
  return { x, y }
}

export function addVec2(left: Vec2, right: Vec2): Vec2 {
  return { x: left.x + right.x, y: left.y + right.y }
}

export function subtractVec2(left: Vec2, right: Vec2): Vec2 {
  return { x: left.x - right.x, y: left.y - right.y }
}

export function scaleVec2(vector: Vec2, scalar: number): Vec2 {
  return { x: vector.x * scalar, y: vector.y * scalar }
}

export function multiplyVec2(left: Vec2, right: Vec2): Vec2 {
  return { x: left.x * right.x, y: left.y * right.y }
}

export function dotVec2(left: Vec2, right: Vec2): number {
  return left.x * right.x + left.y * right.y
}

export function crossVec2(left: Vec2, right: Vec2): number {
  return left.x * right.y - left.y * right.x
}

export function lengthSquaredVec2(vector: Vec2): number {
  return dotVec2(vector, vector)
}

export function lengthVec2(vector: Vec2): number {
  return Math.hypot(vector.x, vector.y)
}

export function distanceSquaredVec2(left: Vec2, right: Vec2): number {
  return lengthSquaredVec2(subtractVec2(left, right))
}

export function distanceVec2(left: Vec2, right: Vec2): number {
  return Math.hypot(left.x - right.x, left.y - right.y)
}

export function normalizeVec2(vector: Vec2, fallback: Vec2 = ZERO_VEC2): Vec2 {
  const length = lengthVec2(vector)
  if (length <= GEOMETRY_EPSILON) return fallback
  return scaleVec2(vector, 1 / length)
}

export function perpendicularVec2(vector: Vec2): Vec2 {
  return { x: -vector.y, y: vector.x }
}

export function midpointVec2(left: Vec2, right: Vec2): Vec2 {
  return { x: (left.x + right.x) / 2, y: (left.y + right.y) / 2 }
}

export function lerpVec2(start: Vec2, end: Vec2, amount: number): Vec2 {
  return {
    x: start.x + (end.x - start.x) * amount,
    y: start.y + (end.y - start.y) * amount,
  }
}

export function rotateVec2(vector: Vec2, radians: number): Vec2 {
  const cosine = Math.cos(radians)
  const sine = Math.sin(radians)
  return {
    x: vector.x * cosine - vector.y * sine,
    y: vector.x * sine + vector.y * cosine,
  }
}

export function angleVec2(vector: Vec2): number {
  return Math.atan2(vector.y, vector.x)
}

export function almostEqual(left: number, right: number, epsilon = GEOMETRY_EPSILON): boolean {
  return Math.abs(left - right) <= epsilon
}

export function vec2AlmostEqual(left: Vec2, right: Vec2, epsilon = GEOMETRY_EPSILON): boolean {
  return almostEqual(left.x, right.x, epsilon) && almostEqual(left.y, right.y, epsilon)
}

export function isFiniteVec2(vector: Vec2): boolean {
  return Number.isFinite(vector.x) && Number.isFinite(vector.y)
}

export * from "./command";
export * from "./history";
export * from "./operations";
export * from "./patches";
import type { SceneDocument } from "../model";
import { applyScenePatches, cloneScenePatch, type ScenePatch } from "./patches";

let commandCounter = 0;

function createCommandId(): string {
  commandCounter += 1;
  const suffix = globalThis.crypto?.randomUUID() ?? `${Date.now().toString(36)}-${commandCounter}`;
  return `command:${suffix}`;
}

export interface SceneCommand {
  readonly id: string;
  readonly label: string;
  readonly createdAt: string;
  readonly patches: readonly ScenePatch[];
  execute(scene: SceneDocument): SceneDocument;
  undo(scene: SceneDocument): SceneDocument;
}

export class PatchCommand implements SceneCommand {
  readonly id: string;
  readonly label: string;
  readonly createdAt: string;
  readonly patches: readonly ScenePatch[];

  constructor(label: string, patches: readonly ScenePatch[]) {
    if (patches.length === 0) {
      throw new Error("A command must contain at least one operation patch");
    }
    this.id = createCommandId();
    this.label = label;
    this.createdAt = new Date().toISOString();
    this.patches = patches.map(cloneScenePatch);
  }

  execute(scene: SceneDocument): SceneDocument {
    return applyScenePatches(scene, this.patches, "forward");
  }

  undo(scene: SceneDocument): SceneDocument {
    return applyScenePatches(scene, this.patches, "backward");
  }
}

export class BatchCommand implements SceneCommand {
  readonly id: string;
  readonly label: string;
  readonly createdAt: string;
  readonly commands: readonly SceneCommand[];
  readonly patches: readonly ScenePatch[];

  constructor(label: string, commands: readonly SceneCommand[]) {
    if (commands.length === 0) {
      throw new Error("A batch command must contain at least one command");
    }
    this.id = createCommandId();
    this.label = label;
    this.createdAt = new Date().toISOString();
    this.commands = [...commands];
    this.patches = commands.flatMap((command) => command.patches.map(cloneScenePatch));
  }

  execute(scene: SceneDocument): SceneDocument {
    return this.commands.reduce(
      (currentScene, command) => command.execute(currentScene),
      scene,
    );
  }

  undo(scene: SceneDocument): SceneDocument {
    return [...this.commands]
      .reverse()
      .reduce((currentScene, command) => command.undo(currentScene), scene);
  }
}

