  if (node.width < 0 || node.height < 0 || node.opacity < 0 || node.opacity > 1) {
    issues.push(
      violation(
        'invalid-range',
        `nodes.${node.id}`,
        `Node ${node.id} has invalid dimensions or opacity`,
        node.id,
