export function parseSceneDocumentJson(
  source: string,
  options: JsonImportOptions = {},
): ExportOperationResult<SceneDocument> {
  const maximumBytes = Math.max(1, options.maxBytes ?? DEFAULT_MAX_JSON_BYTES);
