  );
}

function cloneNodeForPaste(
  node: SceneNode,
  id: string,
  parentId: string | null,
  offsetRoot: boolean,
): SceneNode {
  const x = node.x + (offsetRoot ? 16 : 0);
  const y = node.y + (offsetRoot ? 16 : 0);
  if (node.type === 'frame') {
    return cloneSceneNode({ ...node, id, parentId, x, y, childIds: [] });
  }
  if (node.type === 'group') {
    return cloneSceneNode({ ...node, id, parentId, x, y, childIds: [] });
  }
