    const zoom = clampZoom(nextZoom);
    const worldX = (screenX - camera.x) / camera.zoom;
    const worldY = (screenY - camera.y) / camera.zoom;
    this.setCamera({ x: screenX - worldX * zoom, y: screenY - worldY * zoom, zoom });
  }

