    const padding = 74;
    const width = Math.max(1, bounds.maxX - bounds.minX);
    const height = Math.max(1, bounds.maxY - bounds.minY);
    const zoom = clampZoom(
      Math.min((viewport.width - padding * 2) / width, (viewport.height - padding * 2) / height),
    );
