      style={{ left: Math.min(x, window.innerWidth - 252), top: Math.min(y, window.innerHeight - 414) }}
    >
      {ENTRIES.map((entry) => {
        const EntryIcon = entry.icon;
        const requiresSelection = !['paste'].includes(entry.id);
        const isDisabled = (requiresSelection && !hasSelection) || (entry.id === 'ungroup' && !canUngroup);
