              <FileCode2 size={24} />
            ) : (
              <FileJson2 size={24} />
            )}
          </div>
          <div>
            <strong>{format.toUpperCase()}</strong>
            <span>
              {format === 'png'
                ? 'Raster image at a chosen scale'
                : format === 'svg'
                  ? 'Editable vector markup'
                  : 'Complete versioned scene document'}
            </span>
          </div>
        </div>

        <div className="dialog-field">
          <span>Format</span>
          <SegmentedControl
            ariaLabel="Export format"
            value={format}
