          </button>
          <button
            type="button"
            className="primary-action"
            disabled={isExporting}
            onClick={() => void exportFile()}
          >
            {isExporting ? 'Exporting…' : `Export ${format.toUpperCase()}`}
          </button>
        </footer>
      </section>
    </div>
  );
