                onAction(entry.id);
                onClose();
              }}
            >
              <EntryIcon size={15} aria-hidden="true" />
              <span>{entry.label}</span>
              {entry.shortcut ? <kbd>{entry.shortcut}</kbd> : null}
            </button>
          </div>
        );
      })}
    </div>
  );
