        context.stroke();
        continue;
      }
      context.beginPath();
      context.rect(
        handle.point.x - HANDLE_SIZE / 2,
        handle.point.y - HANDLE_SIZE / 2,
        HANDLE_SIZE,
        HANDLE_SIZE,
      );
      context.fill();
      context.stroke();
    }
    context.restore();
  }

