    overrides: NodeRenderOverrides,
    visibleIds: ReadonlySet<string>,
    zoom: number,
  ) {
    const node = document.nodes[nodeId];
    if (!node?.visible) return;

    const values = getDrawValues(node, overrides.get(node.id));
    const localMatrix = composeMatrices(
      translationMatrix(values.x, values.y),
      rotationMatrixDegrees(values.rotation),
    );
    const worldMatrix = composeMatrices(parentMatrix, localMatrix);
    const bounds = transformRectBounds(
      { x: 0, y: 0, width: values.width, height: values.height },
      worldMatrix,
    );
    this.#drawnNodes.set(node.id, { node, values, matrix: worldMatrix, bounds });

    const isContainer = node.type === 'frame' || node.type === 'group';
    const shouldDrawSelf = visibleIds.has(node.id) || overrides.has(node.id);
    const shouldTraverse = isContainer && node.childIds.length > 0;
    if (!shouldDrawSelf && !shouldTraverse) return;

    context.save();
    context.transform(
      localMatrix.a,
      localMatrix.b,
      localMatrix.c,
      localMatrix.d,
      localMatrix.e,
      localMatrix.f,
    );
    context.globalAlpha *= values.opacity;
    context.globalCompositeOperation = BLEND_MODES[node.blendMode];

    // Effects belong to this layer, not to its descendants. Keeping this save/restore
    // boundary is especially important for a blurred or shadowed frame.
    if (shouldDrawSelf) {
      context.save();
      this.#applyEffects(context, node, zoom);
      if (node.type === 'text') this.#drawText(context, node, values);
      else if (node.type === 'image') this.#drawImage(context, node, values);
      else if (node.type !== 'group') this.#drawShape(context, node, values);
      context.restore();
    }

    if (shouldTraverse) {
      if (node.type === 'frame' && node.clipContent) {
        createNodePath(context, node, values);
        context.clip();
      }
      for (const childId of node.childIds) {
        this.#drawNodeTree(context, document, childId, worldMatrix, overrides, visibleIds, zoom);
      }
    }

    context.restore();
  }

  #drawShape(context: CanvasRenderingContext2D, node: SceneNode, values: DrawValues) {
    createNodePath(context, node, values);
    for (const fill of node.fills) {
      if (!fill.visible || fill.opacity <= 0 || node.type === 'line') continue;
      context.save();
      context.fillStyle = paintStyle(context, fill, values.width, values.height);
      context.globalCompositeOperation = BLEND_MODES[fill.blendMode];
      context.fill('evenodd');
      context.restore();
    }
    for (const stroke of node.strokes) applyStroke(context, stroke, values.width, values.height);
  }

  #applyEffects(context: CanvasRenderingContext2D, node: SceneNode, zoom: number) {
    const shadow = node.effects.find((effect) => effect.visible && effect.type === 'drop-shadow');
    if (shadow?.type === 'drop-shadow') {
      context.shadowColor = rgba(shadow.color);
      context.shadowOffsetX = shadow.offset.x;
      context.shadowOffsetY = shadow.offset.y;
      context.shadowBlur = shadow.blur;
    }
    const blur = node.effects.find((effect) => effect.visible && effect.type === 'layer-blur');
    if (blur?.type === 'layer-blur' && zoom > 0.2) context.filter = `blur(${blur.radius}px)`;
  }

  #drawText(
    context: CanvasRenderingContext2D,
    node: Extract<SceneNode, { type: 'text' }>,
    values: DrawValues,
  ) {
    const fill = node.fills.find((candidate) => candidate.visible);
    context.fillStyle = fill
      ? paintStyle(context, fill, values.width, values.height)
      : 'currentColor';
    context.font = `${node.fontStyle} ${node.fontWeight} ${node.fontSize}px "${node.fontFamily}", sans-serif`;
    context.textBaseline = 'top';
    context.textAlign = node.textAlign === 'justify' ? 'left' : node.textAlign;
    const x =
      node.textAlign === 'center'
        ? values.width / 2
        : node.textAlign === 'right'
          ? values.width
          : 0;
    const resolvedLineHeight =
      node.lineHeight <= 4 ? node.fontSize * node.lineHeight : node.lineHeight;
    const lines = wrapText(
      context,
      applyTextCase(node.content, node.textCase),
      values.width,
      node.letterSpacing,
    );
    const blockHeight = lines.length * resolvedLineHeight;
    const y =
      node.verticalAlign === 'center'
        ? (values.height - blockHeight) / 2
        : node.verticalAlign === 'bottom'
          ? values.height - blockHeight
          : 0;

    for (const [index, line] of lines.entries()) {
      context.fillText(line, x, y + index * resolvedLineHeight, values.width);
    }
  }

  #drawImage(
    context: CanvasRenderingContext2D,
    node: Extract<SceneNode, { type: 'image' }>,
    values: DrawValues,
  ) {
    createNodePath(context, node, values);
    context.save();
    context.clip();
    const image = this.#loadImage(node.source.uri);
    if (!image.complete || image.naturalWidth === 0) {
      context.fillStyle = 'oklch(0.24 0.012 260)';
      context.fillRect(0, 0, values.width, values.height);
      context.restore();
      return;
    }

    context.imageSmoothingEnabled = node.smoothing;
    const intrinsicRatio = image.naturalWidth / image.naturalHeight;
    const boxRatio = values.width / values.height;
    let drawWidth = values.width;
    let drawHeight = values.height;

) {
  const worldBounds = transformRectBounds(
    bounds,
    parentWorld ?? { a: 1, b: 0, c: 0, d: 1, e: 0, f: 0 },
  );
  return {
    x: worldBounds.minX,
    y: worldBounds.minY,
    width: worldBounds.maxX - worldBounds.minX,
    height: worldBounds.maxY - worldBounds.minY,
  };
}

function nodeFrameWorldRect(frame: NodeRenderOverride, parentWorld: Matrix2D) {
  const matrix = composeMatrices(
    parentWorld,
    translationMatrix(frame.x ?? 0, frame.y ?? 0),
    rotationMatrixDegrees(frame.rotation ?? 0),
  );
  const bounds = transformRectBounds(
    { x: 0, y: 0, width: frame.width ?? 1, height: frame.height ?? 1 },
    matrix,
  );
  return {
    x: bounds.minX,
    y: bounds.minY,
    width: bounds.maxX - bounds.minX,
    height: bounds.maxY - bounds.minY,
  };
}

function readImageFile(file: File) {
  return new Promise<{ readonly uri: string; readonly width: number; readonly height: number }>(
    (resolve, reject) => {
      const reader = new FileReader();
      reader.onerror = () => reject(new Error('The image could not be read.'));
      reader.onload = () => {
        if (typeof reader.result !== 'string') {
          reject(new Error('The image did not produce a usable data URL.'));
          return;
        }
        const uri = reader.result;
        const image = new Image();
        image.onerror = () => reject(new Error('The image format is not supported.'));
        image.onload = () =>
          resolve({ uri, width: image.naturalWidth, height: image.naturalHeight });
        image.src = uri;
      };
      reader.readAsDataURL(file);
    },
  );
}

function topLevelSelectedNodes(store: EditorStore) {
  const { runtime, session } = store.getSnapshot();
  const { document } = runtime;
  return [...session.selectedIds]
    .filter((id) => {
      const node = document.nodes[id];
      if (!node || node.locked) return false;
      let parentId = node.parentId;
      while (parentId) {
        if (session.selectedIds.has(parentId)) return false;
        parentId = document.nodes[parentId]?.parentId ?? null;
      }
      return true;
    })
    .map((id) => document.nodes[id])
    .filter((node): node is SceneNode => node !== undefined);
}

export function CanvasStage({ store, onContextMenuRequest }: CanvasStageProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const sceneCanvasRef = useRef<HTMLCanvasElement>(null);
  const overlayCanvasRef = useRef<HTMLCanvasElement>(null);
  const textAreaRef = useRef<HTMLTextAreaElement>(null);
  const rendererRef = useRef<SceneRenderer | null>(null);
  const gestureRef = useRef<PointerGesture>({ kind: 'idle' });
  const isSpacePressedRef = useRef(false);
  const renderFrameRef = useRef<number | null>(null);
  const lastCursorUpdateRef = useRef(0);
  const textEditRef = useRef<TextEditState | null>(null);
  const [textEdit, setTextEdit] = useState<TextEditState | null>(null);
  const [isFileDragging, setIsFileDragging] = useState(false);

  textEditRef.current = textEdit;

  useEffect(() => {
    const container = containerRef.current;
    const sceneCanvas = sceneCanvasRef.current;
    const overlayCanvas = overlayCanvasRef.current;
    if (!container || !sceneCanvas || !overlayCanvas) return;

    const scheduleRender = () => {
      if (renderFrameRef.current !== null) return;
      renderFrameRef.current = window.requestAnimationFrame(() => {
        renderFrameRef.current = null;
        const snapshot = store.getSnapshot();
        rendererRef.current?.render(snapshot.runtime, snapshot.session, snapshot.renderOverrides);
        positionTextEditor();
      });
    };

    const renderer = new SceneRenderer(sceneCanvas, overlayCanvas, scheduleRender);
    rendererRef.current = renderer;
    const resizeObserver = new ResizeObserver(([entry]) => {
      if (!entry) return;
      const { width, height } = entry.contentRect;
      renderer.resize(width, height);
      store.setViewport(width, height);
      scheduleRender();
    });
    resizeObserver.observe(container);
    const unsubscribe = store.subscribe(scheduleRender);
    scheduleRender();

    function positionTextEditor() {
      const editor = textAreaRef.current;
      const editing = textEditRef.current;
      if (!editor || !editing) return;
      const snapshot = store.getSnapshot();
      const drawn = renderer.getDrawnNode(editing.nodeId);
      const node = snapshot.runtime.document.nodes[editing.nodeId];
      if (!drawn || node?.type !== 'text') return;
      const zoom = snapshot.session.camera.zoom;
      const origin = {
        x: drawn.matrix.e * zoom + snapshot.session.camera.x,
        y: drawn.matrix.f * zoom + snapshot.session.camera.y,
      };
      const angle = Math.atan2(drawn.matrix.b, drawn.matrix.a);
      editor.style.left = `${origin.x}px`;
      editor.style.top = `${origin.y}px`;
      editor.style.width = `${Math.max(30, node.width * zoom)}px`;
      editor.style.height = `${Math.max(node.fontSize * 1.5, node.height * zoom)}px`;
      editor.style.fontFamily = `"${node.fontFamily}", sans-serif`;
      editor.style.fontSize = `${node.fontSize * zoom}px`;
      editor.style.fontWeight = `${node.fontWeight}`;
      editor.style.lineHeight = `${node.lineHeight <= 4 ? node.lineHeight : node.lineHeight / node.fontSize}`;
      editor.style.color = 'oklch(0.12 0 0)';
      editor.style.transform = `rotate(${angle}rad)`;
    }

    return () => {
      resizeObserver.disconnect();
      unsubscribe();
      if (renderFrameRef.current !== null) window.cancelAnimationFrame(renderFrameRef.current);
      rendererRef.current = null;
    };
  }, [store]);

  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.code === 'Space' && !(event.target instanceof HTMLInputElement)) {
        isSpacePressedRef.current = true;
      }
    };
    const onKeyUp = (event: KeyboardEvent) => {
      if (event.code === 'Space') isSpacePressedRef.current = false;
    };
    window.addEventListener('keydown', onKeyDown);
    window.addEventListener('keyup', onKeyUp);
    return () => {
      window.removeEventListener('keydown', onKeyDown);
      window.removeEventListener('keyup', onKeyUp);
    };
  }, []);

  useEffect(() => {
    const onPaste = (event: ClipboardEvent) => {
      const file = [...(event.clipboardData?.files ?? [])].find((candidate) =>
        candidate.type.startsWith('image/'),
      );
      if (!file) return;
      event.preventDefault();
      const snapshot = store.getSnapshot();
      const screenPoint = {
        x: snapshot.session.viewport.width / 2,
        y: snapshot.session.viewport.height / 2,
      };
      void placeImage(file, screenToWorld(screenPoint, snapshot.session));
    };
    window.addEventListener('paste', onPaste);
    return () => window.removeEventListener('paste', onPaste);
  }, [store]);

  const placeImage = async (file: File, worldPoint: Vec2) => {
    if (file.size > 20 * 1024 * 1024) {
      store.addToast('Image exceeds the 20 MB limit.', 'error');
      return;
    }
    try {
      const image = await readImageFile(file);
      const maxDimension = 420;
      const scale = Math.min(1, maxDimension / Math.max(image.width, image.height));
      const node = createImageNode({
        name: file.name || 'Pasted image',
        x: worldPoint.x,
        y: worldPoint.y,
        width: image.width * scale,
        height: image.height * scale,
        source: {
          kind: 'data-url',
          uri: image.uri,
          mimeType: file.type,
          intrinsicWidth: image.width,
          intrinsicHeight: image.height,
        },
        cornerRadii: { topLeft: 10, topRight: 10, bottomRight: 10, bottomLeft: 10 },
      });
      store.createNode(node);
      store.addToast('Image placed on canvas', 'success');
    } catch (error: unknown) {
      store.addToast(
        error instanceof Error ? error.message : 'The image could not be placed.',
        'error',
      );
    }
  };

  const startTextEdit = (nodeId: string) => {
    const node = store.document.nodes[nodeId];
    if (node?.type !== 'text' || node.locked) return;
    setTextEdit({ nodeId, value: node.content });
    store.select(nodeId);
    store.setInteraction({ kind: 'text-edit', nodeId });
    window.requestAnimationFrame(() => {
      textAreaRef.current?.focus();
      textAreaRef.current?.select();
    });
  };

        data-left-panel={snapshot.session.isLeftPanelOpen ? 'open' : 'closed'}
        data-right-panel={snapshot.session.isRightPanelOpen ? 'open' : 'closed'}
      >
        <LayersPanel
          className="panel panel--left"
          scene={snapshot.document}
          selectedIds={snapshot.session.selectedIds}
          onSelectionChange={(nodeIds) => store.setSelection(nodeIds)}
          onRename={(nodeId, name) => store.renameNode(nodeId, name)}
          onSetVisibility={setNodeVisibility}
          onSetLocked={setNodeLocked}
          onMove={(request) =>
            store.reparent(request.nodeIds, request.targetParentId, request.targetIndex)
          }
        />
        <CanvasStage store={store} onContextMenuRequest={handleContextMenuRequest} />
        <PropertiesPanel
          className="panel panel--right"
          scene={snapshot.document}
          selectedIds={snapshot.session.selectedIds}
          onCommitNodes={(nodes: readonly SceneNode[], label) => store.updateNodes(nodes, label)}
          onAlign={alignNodes}
          onChangeDocument={changeDocumentProperties}
          onExport={handlePropertyExport}
        />
      </main>

      <StatusBar
        cursorWorld={snapshot.session.cursorWorld}
        activeTool={snapshot.session.activeTool}
        selectedCount={snapshot.session.selectedIds.size}
        nodeCount={snapshot.runtime.nodeCount}
        isSnappingEnabled={snapshot.session.isSnappingEnabled}
        isGridVisible={snapshot.session.isGridVisible}
      />

      {isMainMenuOpen ? (
        <MainMenu
          documents={documents}
          activeDocumentId={snapshot.document.id}
          gridVisible={snapshot.session.isGridVisible}
          rulersVisible={snapshot.session.areRulersVisible}
          snappingEnabled={snapshot.session.isSnappingEnabled}
          leftPanelOpen={snapshot.session.isLeftPanelOpen}
          rightPanelOpen={snapshot.session.isRightPanelOpen}
          onAction={handleMainMenuAction}
          onOpenDocument={openDocument}
          onClose={() => setMainMenuOpen(false)}
        />
      ) : null}

      <CommandPalette
        open={snapshot.session.isCommandPaletteOpen}
        actions={commandActions}
        onOpenChange={(open) => store.setCommandPaletteOpen(open)}
      />
      {contextPoint ? (
        <ContextMenu
          x={contextPoint.x}
          y={contextPoint.y}
          hasSelection={hasSelection}
          canUngroup={canUngroup}
          onAction={handleContextAction}
          onClose={() => setContextPoint(null)}
        />
      ) : null}
      {isPreviewOpen ? <PreviewModal store={store} onClose={() => setPreviewOpen(false)} /> : null}
      {isExportOpen ? (
        <ExportDialog
          hasSelection={hasSelection}
          onClose={() => setExportOpen(false)}
          onExport={exportDocument}
        />
      ) : null}

      <ToastViewport
        className="editor-toasts"
        toasts={toastData}
        onDismiss={(toastId) => store.dismissToast(toastId)}
      />
      <input
        ref={importInputRef}
        className="visually-hidden"
        type="file"
        accept="application/json,.json"
        tabIndex={-1}
        aria-hidden="true"
        onChange={(event) => {
          const file = event.currentTarget.files?.[0];
          if (file) void importJsonFile(file);
          event.currentTarget.value = '';
        }}
      />
      <div className="visually-hidden" aria-live="polite" aria-atomic="true">
        {snapshot.lastActionLabel}
      </div>
    </div>
  );
}

