  reorderSelection(direction: 'forward' | 'backward' | 'front' | 'back') {
    const id = [...this.#session.selectedIds][0];
    if (!id) return;
    const siblings = getSiblingIds(this.#document, id);
    const index = siblings.indexOf(id);
    const targetIndex =
      direction === 'front'
        ? siblings.length
        : direction === 'back'
          ? 0
          : direction === 'forward'
